/* Level 05 (Rilgar) code following partupd; generated by tools/overlay_src.py, stubs replaced by C as functions are
   matched. Starts at 0x0029CA28 (was partupd_0029CA28.c). */
#include "common.h"
#include "structs/particle.h"
#include "include_asm.h"
#include "game/moby/mobyutil.h"
#include "asm_functions/executable.h"
#include "game/math/fastfunc.h"

extern int truncate_float_to_s32(float);

extern unsigned char *rilgar_velocity_particle_texture_ptr;

/* Allocates a 0x30-byte record with create_part and fills it from the arguments (pos and vel copied in,
 * a * 210000.0 and a random byte stored, plus the integer arguments); returns it, or 0 if allocation failed. */
unsigned char *create_particle_with_velocity_and_lifetime(void *pos, void *vel, int a2, int a3, int a4, float a) {
    unsigned char *p = create_part(0x30);
    unsigned char *q;
    if (p != 0) {
        int m;
        float two;
        qcopy(&((struct PartBase *)p)->pos, pos);
        q = (unsigned char *)((struct PartBase *)p)->data;
        m = a4 & 0xFFFFFF;
        two = 2.0f;
        ((struct PartBase *)p)->color = m;
        ((struct PartBase *)p)->unk_09 = truncate_float_to_s32(two) + 0x10;
        ((struct PartBase *)p)->blend = 0x44;
        ((struct PartBase *)p)->unk_01 = 0;
        ((struct PartBase *)p)->texture = *rilgar_velocity_particle_texture_ptr;
        ((struct PartBase *)p)->size = a * 210000.0f;
        ((struct PartBase *)p)->spin = random_integer_below(0x100);
        qcopy(q, vel);
        *(float *)(q + 0x10) = two / IntToFloat(a2);
        ((struct PartBase *)p)->timer = a2;
        *(short *)(q + 0x1C) = a3;
        *(int *)(q + 0x14) = m;
        *(int *)(q + 0x18) = a4;
    }
    return p;
}
extern unsigned char *rilgar_random_particle_textures_ptr;

/* spawn a particle at a position with a velocity and random parameters */
unsigned char *create_particle_with_velocity_and_randomized_parameters(void *pos, void *vel, int arg2, int arg3,
                                                                       float a, float b, float c) {
    unsigned char *p = create_part(0x32);
    unsigned char *q;
    if (p != 0) {
        q = (unsigned char *)((struct PartBase *)p)->data;
        qcopy(&((struct PartBase *)p)->pos, pos);
        ((struct PartBase *)p)->unk_09 = truncate_float_to_s32(1.0f) + 0x40;
        ((struct PartBase *)p)->blend = 0x44;
        ((struct PartBase *)p)->unk_01 = 0;
        ((struct PartBase *)p)->texture = rilgar_random_particle_textures_ptr[arg3];
        ((struct PartBase *)p)->color = arg2;
        ((struct PartBase *)p)->size = a * 210000.0f;
        ((struct PartBase *)p)->spin = (int)random_float_between(0.0f, 255.0f);
        ((struct PartBase *)p)->timer = scale_ticks(0xF);
        qcopy(q, vel);
        *(float *)(q + 0x10) = b;
        *(int *)(q + 0x14) = truncate_float_to_s32(random_float_between(-3.0f, 3.0f));
        *(float *)(q + 0x18) = c;
    }
    return p;
}
